import * as React from "react";
import { useLocation } from "@reach/router";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { addDoc, collection, serverTimestamp } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { trackEvent } from "../utils/analytics";

type AuditRequestModalPayload = {
  serviceName?: string;
  source?: string;
};

type AuditRequestContextValue = {
  openModal: (payload?: AuditRequestModalPayload) => void;
  closeModal: () => void;
};

type AuditRequestFormState = {
  name: string;
  email: string;
  company: string;
  website: string;
  service: string;
  goal: string;
  timeline: string;
  message: string;
  honey: string;
};

type AuditRequestButtonProps = {
  children: React.ReactNode;
  className?: string;
  serviceName?: string;
  source?: string;
};

type AuditRequestModalLabels = {
  title: string;
  subtitle: string;
  close: string;
  submit: string;
  submitting: string;
  error: string;
  successTitle: string;
  successMessage: string;
  successClose: string;
  privacy: string;
  fields: {
    name: string;
    email: string;
    company: string;
    website: string;
    service: string;
    goal: string;
    timeline: string;
    message: string;
  };
  placeholders: {
    company: string;
    website: string;
    service: string;
    goal: string;
    message: string;
  };
  timelineOptions: string[];
  trustItems: string[];
};

const AuditRequestModalContext = React.createContext<AuditRequestContextValue | null>(null);

function createInitialFormState(serviceName?: string): AuditRequestFormState {
  return {
    name: "",
    email: "",
    company: "",
    website: "",
    service: serviceName || "",
    goal: "",
    timeline: "",
    message: "",
    honey: "",
  };
}

function useAuditRequestModal() {
  const context = React.useContext(AuditRequestModalContext);

  if (!context) {
    throw new Error("useAuditRequestModal must be used inside AuditRequestModalProvider");
  }

  return context;
}

function AuditRequestModal({
  isOpen,
  payload,
  onClose,
}: {
  isOpen: boolean;
  payload: AuditRequestModalPayload;
  onClose: () => void;
}) {
  const { t, i18n } = useTranslation();
  const location = useLocation();
  const dialogId = React.useId();
  const nameInputRef = React.useRef<HTMLInputElement | null>(null);
  const openedAtRef = React.useRef<number>(0);
  const [formState, setFormState] = React.useState<AuditRequestFormState>(createInitialFormState());
  const [status, setStatus] = React.useState<"idle" | "submitting" | "success" | "error">("idle");

  const labels = t("auditForm", { returnObjects: true }) as AuditRequestModalLabels;
  const language = i18n.language || "fr";

  React.useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const nextFormState = createInitialFormState(payload.serviceName);
    setFormState(nextFormState);
    setStatus("idle");
    openedAtRef.current = Date.now();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", handleKeyDown);

    const focusTimeout = window.setTimeout(() => {
      nameInputRef.current?.focus();
    }, 0);

    return () => {
      window.clearTimeout(focusTimeout);
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, onClose, payload.serviceName]);

  const handleChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = event.target;

    setFormState((currentState) => ({
      ...currentState,
      [name]: value,
    }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const openedForMs = Date.now() - openedAtRef.current;
    const isSpamLikeSubmission = Boolean(formState.honey.trim()) || openedForMs < 1500;

    if (isSpamLikeSubmission) {
      trackEvent("lead_form_submit_blocked", {
        source: payload.source || location.pathname,
        service_name: formState.service.trim() || payload.serviceName || "general",
        language,
      });
      setStatus("success");
      return;
    }

    setStatus("submitting");

    try {
      await addDoc(collection(db, "audit_requests"), {
        name: formState.name.trim(),
        email: formState.email.trim(),
        company: formState.company.trim(),
        website: formState.website.trim(),
        service: formState.service.trim(),
        goal: formState.goal.trim(),
        timeline: formState.timeline.trim(),
        message: formState.message.trim(),
        language,
        source: payload.source || location.pathname,
        pagePath: location.pathname,
        pageUrl: typeof window !== "undefined" ? window.location.href : "",
        createdAt: serverTimestamp(),
        submittedAtIso: new Date().toISOString(),
      });

      trackEvent("lead_form_submit", {
        source: payload.source || location.pathname,
        service_name: formState.service.trim() || payload.serviceName || "general",
        language,
        timeline: formState.timeline.trim(),
      });

      setStatus("success");
    } catch (error) {
      console.error("Error creating audit request", error);
      trackEvent("lead_form_error", {
        source: payload.source || location.pathname,
        service_name: formState.service.trim() || payload.serviceName || "general",
        language,
      });
      setStatus("error");
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby={dialogId}
      className="fixed inset-0 z-[70] flex items-center justify-center px-4 py-8 sm:px-6"
    >
      <button
        type="button"
        aria-label={labels.close}
        className="absolute inset-0 bg-primary/90 backdrop-blur-sm"
        onClick={onClose}
      />

      <div className="relative z-10 w-full max-w-3xl overflow-hidden rounded-3xl border border-neutral/20 bg-secondary shadow-2xl">
        <div className="flex items-start justify-between gap-4 border-b border-neutral/20 px-6 py-5">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
              {payload.serviceName || labels.fields.service}
            </p>
            <h2 id={dialogId} className="mt-2 text-2xl font-semibold tracking-tight text-accent">
              {labels.title}
            </h2>
            <p className="mt-2 max-w-2xl text-sm text-neutral">
              {labels.subtitle}
            </p>
            {labels.trustItems.length ? (
              <div className="mt-4 flex flex-wrap gap-2">
                {labels.trustItems.map((item) => (
                  <span
                    key={item}
                    className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-1 text-xs font-medium text-accent"
                  >
                    {item}
                  </span>
                ))}
              </div>
            ) : null}
          </div>

          <button
            type="button"
            onClick={onClose}
            className="inline-flex items-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent transition-colors hover:bg-primary/70"
          >
            {labels.close}
          </button>
        </div>

        <div className="p-6">
          {status === "success" ? (
            <div className="rounded-2xl border border-neutral/20 bg-primary/60 p-6">
              <h3 className="text-xl font-semibold text-accent">{labels.successTitle}</h3>
              <p className="mt-3 max-w-2xl text-sm text-neutral">{labels.successMessage}</p>
              <button
                type="button"
                onClick={onClose}
                className="mt-5 inline-flex items-center rounded-xl bg-accent px-5 py-3 text-sm font-semibold text-primary transition-opacity hover:opacity-90"
              >
                {labels.successClose}
              </button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid gap-4 md:grid-cols-2">
                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.name}</span>
                  <input
                    ref={nameInputRef}
                    type="text"
                    name="name"
                    value={formState.name}
                    onChange={handleChange}
                    required
                    autoComplete="name"
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  />
                </label>

                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.email}</span>
                  <input
                    type="email"
                    name="email"
                    value={formState.email}
                    onChange={handleChange}
                    required
                    autoComplete="email"
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  />
                </label>

                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.company}</span>
                  <input
                    type="text"
                    name="company"
                    value={formState.company}
                    onChange={handleChange}
                    placeholder={labels.placeholders.company}
                    autoComplete="organization"
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  />
                </label>

                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.website}</span>
                  <input
                    type="text"
                    name="website"
                    value={formState.website}
                    onChange={handleChange}
                    required
                    placeholder={labels.placeholders.website}
                    autoComplete="url"
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  />
                </label>

                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.service}</span>
                  <input
                    type="text"
                    name="service"
                    value={formState.service}
                    onChange={handleChange}
                    required
                    placeholder={labels.placeholders.service}
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  />
                </label>

                <label className="block">
                  <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.timeline}</span>
                  <select
                    name="timeline"
                    value={formState.timeline}
                    onChange={handleChange}
                    required
                    className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                  >
                    <option value="">{labels.fields.timeline}</option>
                    {labels.timelineOptions.map((option) => (
                      <option key={option} value={option}>
                        {option}
                      </option>
                    ))}
                  </select>
                </label>
              </div>

              <label className="block">
                <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.goal}</span>
                <textarea
                  name="goal"
                  value={formState.goal}
                  onChange={handleChange}
                  required
                  rows={4}
                  placeholder={labels.placeholders.goal}
                  className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                />
              </label>

              <label className="block">
                <span className="mb-2 block text-sm font-medium text-accent">{labels.fields.message}</span>
                <textarea
                  name="message"
                  value={formState.message}
                  onChange={handleChange}
                  rows={5}
                  placeholder={labels.placeholders.message}
                  className="w-full rounded-2xl border border-neutral/20 bg-primary px-4 py-3 text-sm text-accent outline-none transition-colors focus:border-accent/35"
                />
              </label>

              <input
                type="text"
                name="honey"
                value={formState.honey}
                onChange={handleChange}
                tabIndex={-1}
                autoComplete="off"
                className="hidden"
                aria-hidden="true"
              />

              {status === "error" ? (
                <p className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
                  {labels.error}
                </p>
              ) : null}

              <div className="flex flex-col gap-3 border-t border-neutral/20 pt-5 sm:flex-row sm:items-center sm:justify-between">
                <p className="max-w-xl text-xs leading-5 text-neutral">{labels.privacy}</p>
                <button
                  type="submit"
                  disabled={status === "submitting"}
                  className="inline-flex items-center justify-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {status === "submitting" ? labels.submitting : labels.submit}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

export function AuditRequestModalProvider({ children }: { children: React.ReactNode }) {
  const [isOpen, setIsOpen] = React.useState(false);
  const [payload, setPayload] = React.useState<AuditRequestModalPayload>({});

  const openModal = (nextPayload?: AuditRequestModalPayload) => {
    setPayload(nextPayload || {});
    setIsOpen(true);
  };

  const closeModal = () => {
    setIsOpen(false);
    setPayload({});
  };

  return (
    <AuditRequestModalContext.Provider value={{ openModal, closeModal }}>
      {children}
      <AuditRequestModal isOpen={isOpen} payload={payload} onClose={closeModal} />
    </AuditRequestModalContext.Provider>
  );
}

export function AuditRequestButton({
  children,
  className,
  serviceName,
  source,
}: AuditRequestButtonProps) {
  const { openModal } = useAuditRequestModal();

  return (
    <button
      type="button"
      onClick={() => {
        trackEvent("service_cta_click", {
          source: source || "unknown",
          service_name: serviceName || "general",
        });
        trackEvent("lead_form_open", {
          source: source || "unknown",
          service_name: serviceName || "general",
        });
        openModal({ serviceName, source });
      }}
      className={className}
    >
      {children}
    </button>
  );
}
