import React from "react";
import { useI18next } from "gatsby-plugin-react-i18next";
import { UserProfile } from "../interfaces"; 
import { saveLanguageSwitchScrollState } from "../utils/languageScroll";

interface NavProps {
  data?: UserProfile;
}

const LanguageSelector: React.FC<NavProps> = ({ data }) => {
  const { languages, changeLanguage, language: currentLanguage } = useI18next();

  if (!data?.menu) {
    return null;
  }

  return (
    <div className={styles.container}>
      <ul className={styles.buttonsWrapper}>
        {languages.map((lng) => (
          <li
            key={lng}
            className={`${styles.buttons} ${lng === currentLanguage ? styles.active : ""}`}
            aria-current={lng === currentLanguage ? "true" : undefined}
            onClick={(e) => {
              e.preventDefault();
              if (lng !== currentLanguage) {
                saveLanguageSwitchScrollState();
                changeLanguage(lng);
              }
            }}
          >
            <div className={styles.text}>{lng}</div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default LanguageSelector;

const styles = {
  container: "flex flex-row justify-center self-center relative",
  buttonsWrapper: "flex justify-evenly flex-row",
  buttons: "bg-terciary flex w-10 h-10 shrink-0 grow-0 justify-center text-light cursor-pointer mx-1 opacity-60",
  active: "opacity-100 border-2 border-primary bg-secondary",
  text: "self-center capitalize",
};
